INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(48011, 'Judges 20:44', 'Judges', 20, 44, 'د بنیامینیانو اتلس زره زړور عسکر ووژل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_44.mp3', '', 1761754199, 1761754199),
(48012, 'Judges 20:45', 'Judges', 20, 45, 'هغه کسان چې ژوندي پاتې وو هغوی په دښته کې د رمون د ګټ خواته وتښتېدل، خو اسراییلیانو په لاره باندې د هغوی پنځه زره تنه ووژل. هغوی تر جدعوم پورې د بنیامینیانو پسې شول او دوه زره تنه یې نور هم ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_45.mp3', '', 1761754199, 1761754199),
(48013, 'Judges 20:46', 'Judges', 20, 46, 'په هغه ورځ د بنیامینیانو پنځه ویشت زره کسان ووژل شول. هغوی ټول زړور عسکر وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_46.mp3', '', 1761754199, 1761754199),
(48014, 'Judges 20:47', 'Judges', 20, 47, 'خو یوازې شپږ سوه تنو وکولای شول چې په دښته کې د رمون ګټ ته وتښتي او څلور میاشتې هغوی هلته پاتې شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_47.mp3', '', 1761754199, 1761754199),
(48015, 'Judges 20:48', 'Judges', 20, 48, 'اسراییلیان د پاتې بنیامینیانو پسې راوګرځېدل او هغوی ټول یې د سړیو، ښځو، ماشومانو او حیواناتو سره ووژل او په هغه سیمه کې یې ټول ښارګوټي وسوځول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges20_verse_48.mp3', '', 1761754199, 1761754199),
(48016, 'Micah 3:1', 'Micah', 3, 1, 'میکاه وویل: «ای د اسراییلو د قوم مشرانو، غوږ ونیسئ! تاسو باید عدالت وپېژنئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_1.mp3', '', 1761754199, 1761754199),
(48017, 'Micah 3:2', 'Micah', 3, 2, 'خو تاسو د نېکۍ نه کرکه کوئ او بدي خوښوئ. تاسو لکه قصاب د خلکو نه پوستکي وباسئ او لکه ځنګلي ځناور د هغوی د هډوکو نه غوښې شلوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_2.mp3', '', 1761754199, 1761754199),
(48018, 'Micah 3:3', 'Micah', 3, 3, 'تاسو زما د خلکو غوښې خورئ. تاسو د هغوی نه لکه قصاب پوستکي وباسئ، د هغوی هډوکي ماتوئ او هغوی د غوښې په شان ټوټې ټوټې کوئ او په دېګ کې یې اچوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_3.mp3', '', 1761754199, 1761754199),
(48019, 'Micah 3:4', 'Micah', 3, 4, 'بیا به تاسو څښتن ته فریادونه کوئ، خو هغه به درته ځواب نه درکوي. هغه به ستاسو نه مخ اړوي، ځکه چې تاسو بد کارونه کړي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_4.mp3', '', 1761754199, 1761754199),
(48020, 'Micah 3:5', 'Micah', 3, 5, 'دا هغه څه دي چې څښتن یې وایي: «تاسو جعلي پیغمبران زما خلک غولوئ، تاسو د هغو خلکو دپاره د سولې او سلامتۍ وعده کوئ چې خواړه درکوي، خو څوک چې خواړه نه ورکوي، هغوی په جنګ باندې وېروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_5.mp3', '', 1761754199, 1761754199),
(48021, 'Micah 3:6', 'Micah', 3, 6, 'نو ای پیغمبرانو، په تاسو باندې به شپه راشي چې رویا به په کې نه وي او تیاره به راشي چې پېشګویي به نه وي. لمر به پرېوځي او ورځ به درته تیاره وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_6.mp3', '', 1761754199, 1761754199),
(48022, 'Micah 3:7', 'Micah', 3, 7, 'غیب ویونکي به وشرمیږي او فال کتونکي به رسوا شي. هغوی به د خجالت نه خپل مخونه پټ کړي، ځکه چې زه به هغوی ته ځواب نه ورکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_7.mp3', '', 1761754199, 1761754199),
(48023, 'Micah 3:8', 'Micah', 3, 8, 'میکاه وویل: «خو د خپل ځان په هکله باید ووایم چې څښتن زه د خپل قدرت او روح نه ډک کړی یم او ماته یې د عدالت کولو احساس او جرات راکړی دی چې د اسراییلو خلکو ته د هغوی ګناهونه وروښایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_8.mp3', '', 1761754199, 1761754199),
(48024, 'Micah 3:9', 'Micah', 3, 9, 'ای د اسراییلو مشرانو، تاسو چې د عدالت نه کرکه کوئ او نېکي په بدۍ بدلوئ، نو ماته غوږ ونیسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_9.mp3', '', 1761754199, 1761754199),
(48025, 'Micah 3:10', 'Micah', 3, 10, 'تاسو د قتلونو او بې‌انصافۍ له مخې صهیون یعنې اورشلیم جوړوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_10.mp3', '', 1761754199, 1761754199),
(48026, 'Micah 3:11', 'Micah', 3, 11, 'د ښار حاکمان رشوتونه اخلي، کاهنان یوازې د پیسو په خاطر د خدای د قوانینو په هکله تعلیم ورکوي، پیغمبران په پیسو باندې پېشګویانې کوي او هغوی ټول دعوه کوي چې دوی په څښتن باندې تکیه کوي. هغوی وایي: ‹مونږ ته به هېڅ کوم زیان نه رارسیږي، ځکه چې څښتن زمونږ سره مل دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_11.mp3', '', 1761754199, 1761754199),
(48027, 'Micah 3:12', 'Micah', 3, 12, 'نو ستاسو په سبب به صهیون لکه د پټي په شان قلبه شي، اورشلیم به په کنډوالو باندې بدل شي او د صهیون غر نه به چې د خدای کور ورباندې جوړ شوی دی، ځنګل جوړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/micah3_verse_12.mp3', '', 1761754199, 1761754199),
(48028, 'Genesis 35:1', 'Genesis', 35, 1, 'خدای یعقوب ته وویل: «پاڅه او بیت‌ییل ته لاړ شه او هلته اوسېږه. ما یعنې خپل خدای ته چې په هغه وخت کې چې د خپل ورور عیسو څخه تښتېدلی درښکاره شو، د قربانۍ ځای جوړ کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_1.mp3', '', 1761754199, 1761754199),
(48029, 'Genesis 35:2', 'Genesis', 35, 2, 'نو یعقوب خپلې کورنۍ او هغو ټولو خلکو ته چې د هغه سره وو، وویل: «هغه بتان چې تاسو سره دي، هغه لېرې وغورځوئ. خپل ځانونه پاک کړئ او پاک کالي واغوندئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_2.mp3', '', 1761754199, 1761754199),
(48030, 'Genesis 35:3', 'Genesis', 35, 3, 'راځئ چې بیت‌ییل ته لاړ شو او هلته د هغه خدای دپاره د قربانۍ ځای جوړ کړو چې زما سره یې د سختۍ په وخت کې مرسته کړې وه او هر‌چېرته چې زه تللی یم زما سره مل ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_3.mp3', '', 1761754199, 1761754199),
(48031, 'Genesis 35:4', 'Genesis', 35, 4, 'نو هغوی ټول بتان او همدارنګه هغه غوږوالۍ چې د هغوی په غوږونو کې وې یعقوب ته ورکړې او یعقوب هغه په شکیم کې د څېړۍ د ونې لاندې ښخ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_4.mp3', '', 1761754199, 1761754199),
(48032, 'Genesis 35:5', 'Genesis', 35, 5, 'هغوی روان شول او په شاوخوا ښارونو باندې د خدای وېره راغله. نو ځکه هېڅوک په هغوی پسې نه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_5.mp3', '', 1761754199, 1761754199),
(48033, 'Genesis 35:6', 'Genesis', 35, 6, 'یعقوب د خپلو ټولو خلکو سره لوز ته چې د بیت‌ییل په نوم مشهور دی او د کنعان په خاوره کې دی، راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_6.mp3', '', 1761754199, 1761754199),
(48034, 'Genesis 35:7', 'Genesis', 35, 7, 'هلته هغه د قربانۍ ځای جوړ کړ او هغه ځای یې د بیت‌ییل د خدای په نوم یاد کړ، ځکه په هغه ځای کې چې کله یعقوب د خپل ورور عیسو څخه تښتېده، خدای خپل ځان هغه ته ښکاره کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_7.mp3', '', 1761754199, 1761754199),
(48035, 'Genesis 35:8', 'Genesis', 35, 8, 'د ربکا دایي دبوره مړه شوه او د بیت‌ییل څخه ښکته د څېړۍ د ونې لاندې یې ښخه کړه. نو هغه ونه د ژړا د څېړۍ د ونې په نوم یاده شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_8.mp3', '', 1761754199, 1761754199),
(48036, 'Genesis 35:9', 'Genesis', 35, 9, 'کله چې یعقوب د بین‌النهرین څخه بېرته راستون شو، نو خدای یوځل بیا هغه ته ښکاره شو او برکت یې ورته ورکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_9.mp3', '', 1761754199, 1761754199),
(48037, 'Genesis 35:10', 'Genesis', 35, 10, 'خدای هغه ته وویل: «ستا نوم یعقوب دی. خو له دې وروسته دې ستا نوم یعقوب نه وي، بلکې ستا نوم دې اسراییل وي.» نو د هغه نوم یې اسراییل کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_10.mp3', '', 1761754199, 1761754199),
(48038, 'Genesis 35:11', 'Genesis', 35, 11, 'خدای هغه ته وویل: «زه مطلق قادر خدای یم. ته دې د زیاتو اولادونو خاوند شې. ستا څخه به قومونه پیدا شي او ستا د نسل څخه به پاچاهان پیدا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_11.mp3', '', 1761754199, 1761754199),
(48039, 'Genesis 35:12', 'Genesis', 35, 12, 'هغه ځمکه چې ابراهیم او اسحاق ته مې ورکړې وه، هغه به تاته درکړم او ستا څخه وروسته به یې ستا اولادې ته ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_12.mp3', '', 1761754199, 1761754199),
(48040, 'Genesis 35:13', 'Genesis', 35, 13, 'نو خدای له هغه ځای څخه چې د هغه سره یې خبرې وکړې، پورته وخوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_13.mp3', '', 1761754199, 1761754199),
(48041, 'Genesis 35:14', 'Genesis', 35, 14, 'یعقوب په هغه ځای کې چې خدای ورسره خبرې کړې وې، یوه یادګاري تیږه ودروله او په هغې باندې یې د څښلو نذرانه او د زیتونو تېل واچول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_14.mp3', '', 1761754199, 1761754199),
(48042, 'Genesis 35:15', 'Genesis', 35, 15, 'یعقوب د هغه ځای نوم چې هلته خدای ورسره خبرې کړې وې، بیت‌ییل کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_15.mp3', '', 1761754199, 1761754199),
(48043, 'Genesis 35:16', 'Genesis', 35, 16, 'نو بیا هغوی د بیت‌ییل څخه کډه وکړه. افراتې ته یو څه فاصله پاتې وه چې د راحیل د ماشوم د زېږولو وخت راورسېد او د هغې تکلیف زیات شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_16.mp3', '', 1761754199, 1761754199),
(48044, 'Genesis 35:17', 'Genesis', 35, 17, 'څرنګه چې د ماشوم د زېږولو په وخت کې هغه په ډېر سخت تکلیف کې وه، نو د هغې دایي ورته وویل: «راحیل، مه وېرېږه، دا دې بل زوی دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_17.mp3', '', 1761754199, 1761754199),
(48045, 'Genesis 35:18', 'Genesis', 35, 18, 'خو هغه د مړینې په حال کې وه او د ساه ورکولو په وخت کې یې د هغه نوم بن‌اوني کېښود، خو یعقوب هغه بنیامین وباله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_18.mp3', '', 1761754199, 1761754199),
(48046, 'Genesis 35:19', 'Genesis', 35, 19, 'نو راحیل مړه شوه او هغه یې د افراتې لارې ته نژدې چې اوس د بیت‌لحم په نوم یادیږي، ښخه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_19.mp3', '', 1761754199, 1761754199),
(48047, 'Genesis 35:20', 'Genesis', 35, 20, 'یعقوب د هغې په قبر باندې یادګاري تیږه ودروله او تر نن ورځې پورې هغه د راحیل د قبر نښه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_20.mp3', '', 1761754199, 1761754199),
(48048, 'Genesis 35:21', 'Genesis', 35, 21, 'نو یعقوب بیا کډه وکړه او د عیدر د برج بلې خواته یې خپلې خېمې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_21.mp3', '', 1761754199, 1761754199),
(48049, 'Genesis 35:22', 'Genesis', 35, 22, 'هغه وخت چې یعقوب په هغې سیمه کې اوسېده، روبین لاړ او د خپل پلار د وینځې بلهې سره یې زنا وکړه او یعقوب د دې څخه خبر شو. یعقوب دولس زامن درلودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_22.mp3', '', 1761754199, 1761754199),
(48050, 'Genesis 35:23', 'Genesis', 35, 23, 'د لیه زامن: روبین د یعقوب مشر زوی، شمعون، لاوي، یهودا، یساکار او زبولون.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_23.mp3', '', 1761754199, 1761754199),
(48051, 'Genesis 35:24', 'Genesis', 35, 24, 'د راحیل زامن: یوسف او بنیامین.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_24.mp3', '', 1761754199, 1761754199),
(48052, 'Genesis 35:25', 'Genesis', 35, 25, 'د راحیل د وینځې بلهه زامن: دان او نفتالي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_25.mp3', '', 1761754199, 1761754199),
(48053, 'Genesis 35:26', 'Genesis', 35, 26, 'د لیه د وینځې زلفه زامن: جاد او اشیر. دا د یعقوب زامن وو چې په بین‌النهرین کې زېږېدلي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_26.mp3', '', 1761754199, 1761754199),
(48054, 'Genesis 35:27', 'Genesis', 35, 27, 'یعقوب خپل پلار اسحاق ته چې قریت‌اربع (حبرون) ته نژدې په ممري کې ؤ یعنې هغه ځای ته چې ابراهیم او اسحاق په کې اوسېدل، راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_27.mp3', '', 1761754199, 1761754199),
(48055, 'Genesis 35:28', 'Genesis', 35, 28, 'اسحاق یوسلو اتیا کاله ژوند وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_28.mp3', '', 1761754199, 1761754199),
(48056, 'Genesis 35:29', 'Genesis', 35, 29, 'هغه په پاخه عمر کې مړ شو او د خپلو نیکونو سره یوځای شو. د هغه زامنو عیسو او یعقوب هغه ښخ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis35_verse_29.mp3', '', 1761754199, 1761754199),
(48057, 'Judges 17:1', 'Judges', 17, 1, 'د افرایم په غرنۍ سیمه کې یو سړی چې نوم یې میخا ؤ، اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_1.mp3', '', 1761754199, 1761754199),
(48058, 'Judges 17:2', 'Judges', 17, 2, 'یوه ورځ هغه خپلې مور ته وویل: «ایا هغه یوولس سوه د سپینو زرو سکې دې په یاد دي چې ستا څخه غلا شوي وو؟ کله چې تا هغه کس ته چې هغه یې پټ کړي وو ښېرې وکړلې زه په هغه ځای کې وم. دا کار ما کړی ؤ.» مور یې وویل: «زویه څرنګه چې تا اقرار وکړ، نو څښتن دې تاته برکت درکړي!»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_2.mp3', '', 1761754199, 1761754199),
(48059, 'Judges 17:3', 'Judges', 17, 3, 'هغه سپین زر بېرته خپلې مور ته ورکړل او هغې وویل: «زه دا سپین زر د خپل زوی له خوا څښتن ته وقف کوم. د دې څخه به د لرګي د بت په جوړولو کې چې د سپینو زرو پوښ به ورته ورکړل شي، کار واخیستل شي. نو زه به دا سپین زر بېرته تاته درکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_3.mp3', '', 1761754199, 1761754199),
(48060, 'Judges 17:4', 'Judges', 17, 4, 'خو هغه دا سپین زر بېرته خپلې مور ته ورکړل. هغې دوه سوه د سپینو زرو سکې واخیستلې او یو زرګر ته یې ورکړل او هغه د لرګي یو بت جوړ کړ او د سپینو زرو پوښ یې ورته ورکړ. بیا یې هغه د میخا په کور کې کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_4.mp3', '', 1761754199, 1761754199),
(48061, 'Judges 17:5', 'Judges', 17, 5, 'میخا بتخانه درلودله. هغه یو څو بتان او یو سپېڅلی پېشبند جوړ کړ او د خپلو زامنو څخه یې یو تن د خپل کاهن په توګه وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_5.mp3', '', 1761754199, 1761754199),
(48062, 'Judges 17:6', 'Judges', 17, 6, 'په هغه زمانه کې اسراییلو پاچا نه درلود، نو هرچا به هغه کارونه کول چې زړه یې غوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_6.mp3', '', 1761754199, 1761754199),
(48063, 'Judges 17:7', 'Judges', 17, 7, 'په دې وخت کې هلته یو ځوان لاوي ؤ چې د یهودا د بیت لحم په ښارګوټي کې اوسېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_7.mp3', '', 1761754199, 1761754199),
(48064, 'Judges 17:8', 'Judges', 17, 8, 'هغه د بیت لحم څخه لاړ چې د اوسېدلو دپاره کوم بل ځای پیدا کړي. هغه په لاره کې د میخا کور ته چې د افرایم په غرنۍ سیمه کې ؤ، راغی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_8.mp3', '', 1761754199, 1761754199),
(48065, 'Judges 17:9', 'Judges', 17, 9, 'میخا د هغه څخه پوښتنه وکړه: «ته د کوم ځای څخه راغلی یې؟» هغه په ځواب کې وویل: «زه لاوي یم او په یهودا کې د بیت لحم څخه یم. د اوسېدلو دپاره ځای لټوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_9.mp3', '', 1761754199, 1761754199),
(48066, 'Judges 17:10', 'Judges', 17, 10, 'میخا وویل: «زما سره واوسېږه او زما مشاور او کاهن شه. زه به تاته په کال کې لس د سپینو زرو سکې، یو څه کالي او ډوډۍ درکوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_10.mp3', '', 1761754199, 1761754199),
(48067, 'Judges 17:13', 'Judges', 17, 13, 'میخا وویل: «اوس زه پوهېږم چې څښتن به راته برکت راکړي، ځکه چې دغه لاوي زما کاهن دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/judges17_verse_13.mp3', '', 1761754199, 1761754199),
(48068, 'Nehemiah 1:1', 'Nehemiah', 1, 1, 'دا د هغو کارونو ځانګړی رپوټ دی چې نحمیا د حکلیا زوی سرته رسولي دي: د کیسلو په میاشت کې چې د ارتخششتا د پاچاهۍ شلم کال ؤ، زه نحمیا د شوش په بالاحصار کې وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_1.mp3', '', 1761754199, 1761754199),
(48069, 'Nehemiah 1:2', 'Nehemiah', 1, 2, 'زما د ورونو څخه یو تن چې حناني نومېده، د څو کسانو سره د یهودا څخه راغلی ؤ. ما د هغوی څخه د اورشلیم او نورو یهودیانو په اړه چې په بابل کې د جلاوطنۍ څخه تښتېدلي وو، پوښتنه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_2.mp3', '', 1761754199, 1761754199),
(48070, 'Nehemiah 1:3', 'Nehemiah', 1, 3, 'هغوی ماته ځواب راکړ: «هغه خلک چې ژوندي پاتې دي او بېرته د یهودا ولایت ته راغلي دي، د ډېرو کړاوونو او رسوایۍ سره مخامخ دي. د اورشلیم دېوالونه راغورځول شوي دي او د هغه دروازې سوځېدلې دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_3.mp3', '', 1761754199, 1761754199),
(48071, 'Nehemiah 1:4', 'Nehemiah', 1, 4, 'کله چې ما دا ټولې خبرې واورېدلې، نو کښېناستم او په ژړا شوم. څو ورځې مې ویر وکړ او روژه مې ونیوله. د اسمانونو خدای ته مې دعا وکړه:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_4.mp3', '', 1761754199, 1761754199),
(48072, 'Nehemiah 1:5', 'Nehemiah', 1, 5, '«ای د اسمانونو څښتنه خدایه! ته ډېر لوی او هیبتناکه یې. هرڅوک چې ستا سره مینه کوي او ستا په حکمونو باندې عمل کوي، ته په وفادارۍ د هغه سره په خپل لوظ باندې ولاړ یې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_5.mp3', '', 1761754199, 1761754199),
(48073, 'Nehemiah 1:6', 'Nehemiah', 1, 6, 'ای څښتنه، ماته وګوره، او د خپل خدمتګار هغه دعا واوره چې شپه او ورځ یې ستا د خدمتګارانو یعنې د اسراییلو د قوم دپاره کوم. زه په هغو ګناهونو باندې اقرار کوم چې مونږ اسراییلیانو ستا په وړاندې کړي دي. حتی ما او زما خپلې کورنۍ هم ګناه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_6.mp3', '', 1761754199, 1761754199),
(48074, 'Nehemiah 1:7', 'Nehemiah', 1, 7, 'مونږ ستا په وړاندې بد عمل کړی دی او ستا حکمونه مو سرته نه دي رسولي. مونږ د هغو قوانینو څخه پیروي نه ده کړې چې د خپل خدمتګار موسی په وسیله دې مونږ ته راکړي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_7.mp3', '', 1761754199, 1761754199),
(48075, 'Nehemiah 1:8', 'Nehemiah', 1, 8, 'هغه خبره چې تا موسی ته کړې وه، اوس هغه در په یاد کړه. تا ویلي وو: ‹که چېرې تاسو د اسراییلو قوم زما سره بې وفایي وکړه، نو زه به تاسو د نورو قومونو په منځ کې خواره واره کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_8.mp3', '', 1761754199, 1761754199),
(48076, 'Nehemiah 1:9', 'Nehemiah', 1, 9, 'خو که چېرې تاسو بېرته زما خواته راوګرځئ او زما په حکمونو باندې عمل وکړئ، حتی که د نړۍ په کنجونو کې هم خواره واره شوي یئ، زه به تاسو بېرته هغه ځای ته راولم چې ما د خپل عبادت دپاره غوره کړی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_9.mp3', '', 1761754199, 1761754199),
(48077, 'Nehemiah 1:10', 'Nehemiah', 1, 10, 'ای څښتنه، دا ستا خدمتګاران دي او ستا خپل قوم دی. تا هغوی په خپل لوی قوت او طاقت سره ازاد کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_10.mp3', '', 1761754199, 1761754199),
(48078, 'Nehemiah 1:11', 'Nehemiah', 1, 11, 'اوس زما دعا او د خپلو نورو ټولو خدمتګارانو دعا چې غواړي ستا درناوی وکړي، قبوله کړه. زه زارۍ او غوښتنه کوم کله چې نن د پاچا حضور ته ورځم، نو زما سره مرسته وکړه او د هغه زړه نرم کړه، ترڅو زما غوښتنه ومني.» په هغو ورځو کې زه د پاچا ساقي وم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah1_verse_11.mp3', '', 1761754199, 1761754199),
(48079, 'Isaiah 55:1', 'Isaiah', 55, 1, 'څښتن وایي: «ای هغو خلکو، چې یئ تږي راشئ او وڅښئ اوبه تاسو چې نه لرئ پیسې راشئ غله واخلئ او ویې خورئ راشئ واخلئ شراب او شیدې دا دي وړیا تاسو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_1.mp3', '', 1761754199, 1761754199),
(48080, 'Isaiah 55:2', 'Isaiah', 55, 2, 'کوم شیان چې د خوړلو نه دي نو لګوئ ولې پیسې ورباندې؟ ولې تاسو لګوئ د تڼاکو لاسونو پیسې او بیاهم پاتې کېږئ وږي؟ ونیسئ غوږ ماته په ځیر سره او ښه خوراک کوئ، تاسو به خوند واخلئ د ښو خوړو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_2.mp3', '', 1761754199, 1761754199),
(48081, 'Isaiah 55:3', 'Isaiah', 55, 3, 'ای زما خلکو، ونیسئ غوږ ماته په ځیر سره او راشئ ماته ونیسئ غوږ ترڅو ژوندي واوسئ! وبه کړم تاسو سره یو لوظ ابدي دربه کړم هغه باوري او تلپاتې مینه چې د داود سره مې کړې وه وعده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_3.mp3', '', 1761754199, 1761754199),
(48082, 'Isaiah 55:4', 'Isaiah', 55, 4, 'ګورئ، هغه مې وټاکه قوماندان او د قومونو مشر او ما وښود خپل قدرت هغوی ته په وسیله د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_4.mp3', '', 1761754199, 1761754199),
(48083, 'Isaiah 55:5', 'Isaiah', 55, 5, 'اوس به راوغواړئ پردي قومونه تاسو چې یو وخت هغوی نه پېژندلئ تاسو خو هغوی به راشي اوس په منډه منډه ځکه ستاسو څښتن خدای، سپېڅلي خدای د اسراییلو دربخښلی دی عزت او ویاړ تاسو ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_5.mp3', '', 1761754199, 1761754199),
(48084, 'Isaiah 55:6', 'Isaiah', 55, 6, 'اوس چې موندلی شئ څښتن، نو د هغه وکړئ لټون اوس چې نژدې دی څښتن، په هغه غږ وکړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_6.mp3', '', 1761754199, 1761754199),
(48085, 'Isaiah 55:7', 'Isaiah', 55, 7, 'بد عمله خلک دې پرېږدي خپلې بدې لارې بد خیالونه دې بدل کړي خپل هغوی دې وکړي رجوع څښتن ته چې پرې وکړي رحم رجوع دې وکړي زمونږ خدای ته ځکه بخښنه د هغه نه لري پای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_7.mp3', '', 1761754199, 1761754199),
(48086, 'Isaiah 55:8', 'Isaiah', 55, 8, 'څښتن داسې وایي: «زما خیالونه نه دي ستاسو د خیالونو په شان او نه مې هم لارې دي ستاسو د لارو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_8.mp3', '', 1761754199, 1761754199),
(48087, 'Isaiah 55:9', 'Isaiah', 55, 9, 'لکه څنګه چې له ځمکې نه اوچت دي اسمانونه داسې اوچت دي زما خیالونه او زما لارې هم ستاسو د خیالونو او لارو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_9.mp3', '', 1761754199, 1761754199),
(48088, 'Isaiah 55:10', 'Isaiah', 55, 10, 'لکه څنګه چې وریږي باران او واوره له اسمانه او هغه نه ځي بېرته پورته ترڅو خړوبه نه کړي ځمکه تیاروي ځمکه د کښت دپاره، راشنه کوي فصلونه تياروي تخم د کښت دپاره او خواړه خوراک دپاره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_10.mp3', '', 1761754199, 1761754199),
(48089, 'Isaiah 55:11', 'Isaiah', 55, 11, 'نو همداسې کومه خبره چې راوځي زما له خولې بې ثمره به رانه شي هغه بېرته بلکې پوره به کړي زما مقصد هغه او عملي به کړي زما اراده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_11.mp3', '', 1761754199, 1761754199),
(48090, 'Isaiah 55:12', 'Isaiah', 55, 12, 'تاسو به ووځئ د بابل نه په خوشحالۍ سره او په سلامتۍ سره به يووړل شئ خپل وطن ته غرونه او غونډۍ به ستاسو په مخکې سندرې ووایي په لوړ اواز سره او له خوشحالۍ به ټولې ونې پړقوي لاسونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_12.mp3', '', 1761754199, 1761754199),
(48091, 'Isaiah 55:13', 'Isaiah', 55, 13, 'چېرته چې دي اوس د اغزیو بوټي هلته راشنې به شي د سروې ونې او شي راشنې به د اس ونې دا به وي یوه تلپاتې او نه ختمېدونکې نښه دا به ورکړي لوی عزت د څښتن نوم ته»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah55_verse_13.mp3', '', 1761754199, 1761754199),
(48092, 'Job 30:1', 'Job', 30, 1, 'اوس زما نه کشران هم په ما پورې خندا کوى، او دا هغه کشران دى چې د چا پلاران هم زما د رَمو د سپو برابر نۀ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_1.mp3', '', 1761754199, 1761754199),
(48093, 'Job 30:2', 'Job', 30, 2, 'د هغوئ طاقت به ما له څۀ فائده راکړى؟ د هغوئ ټول زور ختم شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_2.mp3', '', 1761754199, 1761754199),
(48094, 'Job 30:3', 'Job', 30, 3, 'هغوئ دومره غريبانان او اوږى وُو چې د شپې به يې په صحرا کښې د بوټو جرړې خوړلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_3.mp3', '', 1761754199, 1761754199),
(48095, 'Job 30:4', 'Job', 30, 4, 'هغوئ د صحرا نه بوټى راويستى دى او خوړلى يې دى، د هغوئ خوراک د جاړو بوټو جرړې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_4.mp3', '', 1761754199, 1761754199),
(48096, 'Job 30:5', 'Job', 30, 5, 'هغوئ د معاشرې نه شړلے شوى دى، او خلق په هغوئ پسې داسې چغې وهى لکه چې دوئ غلۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_5.mp3', '', 1761754199, 1761754199),
(48097, 'Job 30:6', 'Job', 30, 6, 'هغوئ د اوچو شوو دريابونو په مېدانونو کښې ژوند تېروى، او د زمکې په غارونو او ګټو کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_6.mp3', '', 1761754199, 1761754199),
(48098, 'Job 30:7', 'Job', 30, 7, 'هغوئ د غنو بوټو لاندې غوريږى، او د جاړو بوټو لاندې به راغونډيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_7.mp3', '', 1761754199, 1761754199),
(48099, 'Job 30:8', 'Job', 30, 8, 'هغوئ بې‌غېرته او بې‌اصله دى، او د مُلک نه شړلے شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_8.mp3', '', 1761754199, 1761754199),
(48100, 'Job 30:9', 'Job', 30, 9, 'او اوس هغوئ په ما پورې په سندرو کښې خندا کوى، زۀ د هغوئ په سندرو کښې سپک يادېږم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_9.mp3', '', 1761754199, 1761754199),
(48101, 'Job 30:10', 'Job', 30, 10, 'هغوئ زما نه نفرت کوى او هغوئ ما سره هيڅ تعلق نۀ لرى، او ښۀ په زړۀ ورتيا زما په مخ توکاڼى تُوکى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_10.mp3', '', 1761754199, 1761754199),
(48102, 'Job 30:11', 'Job', 30, 11, 'ځکه چې خُدائ پاک زۀ کمزورے او عاجز کړے يم، نو ځکه هغوئ زما ادب نۀ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_11.mp3', '', 1761754199, 1761754199),
(48103, 'Job 30:12', 'Job', 30, 12, 'زما په مخکښې خلق راپاڅى او ومې غورزوى او زما په لار کښې دامونه اچوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_12.mp3', '', 1761754199, 1761754199),
(48104, 'Job 30:13', 'Job', 30, 13, 'هغوئ زما لار بندوى، او هغوئ زما د تباه کولو دپاره هر څۀ کوى، هغوئ ته پته ده چې زما د تپوس کولو والا څوک نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_13.mp3', '', 1761754199, 1761754199),
(48105, 'Job 30:14', 'Job', 30, 14, 'هغوئ په ما باندې د هر طرف نه راشى، کله چې زۀ لاندې يم نو هغوئ په ما باندې راټوپ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_14.mp3', '', 1761754199, 1761754199),
(48106, 'Job 30:15', 'Job', 30, 15, 'اوس زۀ په يره کښې اوسېږم، او زما عزت هوا اوړے دے، او زما مال دولت د وريځو په شان فنا شوے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_15.mp3', '', 1761754199, 1761754199),
(48107, 'Job 30:16', 'Job', 30, 16, 'او اوس زما روح زما نه وتلے دے، او د مصيبت په وخت کښې راګېر يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_16.mp3', '', 1761754199, 1761754199),
(48108, 'Job 30:17', 'Job', 30, 17, 'شپه زما د هډُوکو دپاره د دردونو سبب ګرځى، او چې کوم درد ما خورى په هغې کښې هيڅ کمے نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_17.mp3', '', 1761754199, 1761754199),
(48109, 'Job 30:18', 'Job', 30, 18, 'خپل زورَور لاس سره خُدائ پاک زما جامې نيولې دى، هغۀ زۀ زما د چُوغې د غاړې نه نيولے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_18.mp3', '', 1761754199, 1761754199),
(48110, 'Job 30:19', 'Job', 30, 19, 'هغۀ زۀ خټو ته غورزولے يم، او زۀ د خاورو او ايرو په شان شوے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job30_verse_19.mp3', '', 1761754199, 1761754199);